class IGOWidget {
public:
    bool display;
    virtual ~IGOWidget();
    virtual void SetDisplay(bool);
    virtual void Update(float);
    virtual void Draw();
    IGOWidget();
};

class IconCountWidget : public IGOWidget {
    enum {
        STATE_NONE,
        STATE_ICON,
        STATE_360_SPIN,
        STATE_360_SPIN_SCORE,
        STATE_540_SPIN,
        STATE_540_SPIN_SCORE
    };

    void *objectRoot;
    TextString *iconText;
    TextString *iconCountText;
    float hiliteTime;
    float fade;
    int fadeDir;
    int num_icons;
    int num_spins;
    int state;
    float timer;

public:
    IconCountWidget(int type);
    virtual ~IconCountWidget();
    virtual void SetDisplay(bool);
    virtual void Update(float);
    virtual void Draw();
};

void *operator new(unsigned int, unsigned int, const char *, int);

extern const char source_file[];
extern const char icon_text[];
extern const char zero_text[];
extern const char spin_text[];
__asm__(".equ source_file, 0x004C1430");
__asm__(".equ icon_text, 0x004C0AE0");
__asm__(".equ zero_text, 0x004C09C0");
__asm__(".equ spin_text, 0x004C1458");

enum {
    GOAL_ICON_TETRIS = 12,
    GOAL_SKILL_360_SPIN = 16,
    GOAL_SKILL_540_SPIN = 17,
    GOAL_SKILL_360_SPIN_SCORE = 31,
    GOAL_SKILL_540_SPIN_SCORE = 32
};

IconCountWidget::IconCountWidget(int type)
{
    objectRoot = 0;

    iconText = new (0, source_file, 0) TextString(
        0, icon_text, 214, 62, 10, 0.72f,
        Font::HORIZJUST_RIGHT, Font::VERTJUST_BOTTOM, false,
        color32(255, 255, 255, 255));
    iconCountText = new (0, source_file, 0) TextString(
        0, zero_text, 288, 62, 10, 0.9f,
        Font::HORIZJUST_RIGHT, Font::VERTJUST_BOTTOM, false,
        color32(255, 255, 255, 255));

    fade = 1.0f;
    fadeDir = 1;

    if (type == GOAL_SKILL_360_SPIN) {
        iconText->changeText(spin_text);
        state = STATE_360_SPIN;
    } else if (type == GOAL_SKILL_360_SPIN_SCORE) {
        iconText->changeText(spin_text);
        state = STATE_360_SPIN_SCORE;
    } else if (type == GOAL_SKILL_540_SPIN) {
        iconText->changeText(spin_text);
        state = STATE_540_SPIN;
    } else if (type == GOAL_SKILL_540_SPIN_SCORE) {
        iconText->changeText(spin_text);
        state = STATE_540_SPIN_SCORE;
    } else if (type == GOAL_ICON_TETRIS) {
        state = STATE_ICON;
    } else {
        state = STATE_NONE;
    }

    display = false;
    timer = -1.0f;
}
